  function revisionPreview(source){const data=documentData(source),quote=source==='cotizacion'?clientProjection():null,images=['diseño','costura','empaque'].includes(source)?{...o().images}:null;const fingerprint=JSON.stringify({data,quote,images});const last=revisions.filter(x=>x.client===o().id&&x.source===source).at(-1);return {source,client:o().id,name:o().name,version:last&&last.fingerprint===fingerprint?last.version:(last?last.version+1:1),data,quote,images,fingerprint,existing:last&&last.fingerprint===fingerprint?last:null};}
