  function docTable(data,limit=40){return '<div class="pia-doc-table-wrap"><table class="pia-doc-table '+(data.heads.length>4?'wide':'')+'"><thead><tr>'+data.heads.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+data.rows.slice(0,limit).map(row=>'<tr>'+row.map((x,i)=>'<td>'+(data.money.includes(i)&&typeof x==='number'?money(x):esc(x))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+(data.summary?'<hr class="pia-divider">'+data.summary.map(x=>'<div class="pia-account-line"><span>'+esc(x[0])+'</span><span>'+(typeof x[1]==='number'?money(x[1]):esc(x[1]))+'</span></div>').join(''):'')+(data.rows.length>limit?'<small style="margin-top:9px">Vista de '+limit+' de '+data.rows.length+' registros. La descarga incluye todos los registros.</small>':'');}
