    p+=format==='pdf'?(source==='cotizacion'?quoteDocument(rev):genericDocument(rev)):'<section class="pia-doc-sheet">'+docHeader(rev)+'<div class="pia-doc-title">'+sourceNames[source]+'</div><small>Copia editable · '+esc(rev.name)+'</small>'+docTable(rev.data)+'</section>';
